    est: { weighted: 'Media ponderata', mean: 'Media aritmetica', median: 'Mediana', trimmed: 'Media troncata' },
    cUnit: (e) => `Valore unitario adottato (${e})`, cArea: '× Superficie di riferimento', cDwelling: (n) => `Valore ${n.of}`, cParking: '+ Posto auto',
